// Punto de entrada de la aplicación Angular

import { bootstrapApplication } from '@angular/platform-browser';
import { provideRouter, withPreloadAllModules } from '@angular/router';
import { provideHttpClient, withInterceptors } from '@angular/platform-browser/http';
import { provideAnimations } from '@angular/platform-browser/animations';
import { AppComponent } from './app/app.component';
import { routes } from './app/app.routes';

bootstrapApplication(AppComponent, {
  providers: [
    provideRouter(routes, withPreloadAllModules()),
    provideHttpClient(),
    provideAnimations(),
  ],
}).catch((err) => console.error(err));
